#!/usr/bin/env python3
# Generated by Codex CLI 0.144.6 (GPT-6).
"""Record a bounded physical Xbox clip and restore the KVM codec afterward."""
import argparse
import json
from pathlib import Path
import time
import urllib.parse
import urllib.request

p = argparse.ArgumentParser(description=__doc__)
p.add_argument('output', type=Path)
p.add_argument('--url', default='http://192.168.1.169')
p.add_argument('--seconds', type=int, default=60)
a = p.parse_args()
if not 1 <= a.seconds <= 60:
    p.error('Use 1..60 seconds')
a.output.mkdir(parents=True, exist_ok=False)

def request(path, method='GET', data=None):
    body = json.dumps(data).encode() if data is not None else None
    req = urllib.request.Request(a.url + path, data=body, method=method,
                                 headers={'Content-Type': 'application/json'})
    with urllib.request.urlopen(req, timeout=15) as r:
        return json.load(r)

before = request('/api/v1/settings')
(a.output / 'settings-before.json').write_text(json.dumps(before, indent=2))
if request('/api/v1/record/status')['on']:
    raise SystemExit('An existing recording is active; leaving it untouched')
started = False
try:
    request('/api/v1/settings', 'PUT', {'vid_codec': 1})
    time.sleep(2)
    status = request('/api/v1/record/start?seconds=' + str(a.seconds), 'POST')
    started = True
    print(json.dumps(status), flush=True)
    for _ in range(a.seconds // 5 + 4):
        time.sleep(5)
        status = request('/api/v1/record/status')
        if not status['on']:
            break
    if status['on']:
        status = request('/api/v1/record/stop', 'POST')
    started = False
    (a.output / 'record.json').write_text(json.dumps(status, indent=2))
    print(json.dumps(status), flush=True)
    path = status['file']
    if path:
        url = a.url + '/api/v1/captures/file?' + urllib.parse.urlencode({'path': path})
        with urllib.request.urlopen(url, timeout=30) as r, (a.output / Path(path).name).open('xb') as out:
            while True:
                block = r.read(65536)
                if not block:
                    break
                out.write(block)
finally:
    try:
        if started:
            request('/api/v1/record/stop', 'POST')
    finally:
        request('/api/v1/settings', 'PUT', {'vid_codec': before['vid_codec']})
        print('Restored KVM codec', before['vid_codec'], flush=True)
